'use client'

import { useId, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Card, type CardProps } from '../../data-display/Card'
import styles from './ActionPanel.module.css'

export interface ActionPanelProps extends Omit<CardProps, 'title' | 'onClick' | 'render' | 'orientation'> {
  title: ReactNode
  description?: ReactNode
  action: ReactNode
  actionPlacement?: 'below' | 'end'
  variant?: 'default' | 'danger'
  headingLevel?: 2 | 3 | 4
}

/**
 * A card that offers one action: what it is, what it does, and the control
 * that does it. The panel is a group named by its title and described by
 * its description, so the control is announced with that context.
 */
export function ActionPanel({
  title,
  description,
  action,
  actionPlacement = 'below',
  variant = 'default',
  headingLevel = 2,
  className,
  ...props
}: ActionPanelProps) {
  const id = useId()
  const Heading = `h${headingLevel}` as const
  return (
    <Card
      role="group"
      aria-labelledby={`${id}title`}
      aria-describedby={description ? `${id}description` : undefined}
      className={cn(styles.actionPanel, styles[actionPlacement], variant === 'danger' && styles.danger, className)}
      {...props}
    >
      <div className={styles.text}>
        <Heading id={`${id}title`} className={styles.title}>
          {title}
        </Heading>
        {description && (
          <div id={`${id}description`} className={styles.description}>
            {description}
          </div>
        )}
      </div>
      <div className={styles.action}>{action}</div>
    </Card>
  )
}

/* The Card spaces the text and the action with its own padding and gap. */
.text {
  display: grid;
  gap: var(--space-2);
  min-inline-size: 0;
}

.title {
  margin: 0;
  font-size: var(--text-heading-sm);
  line-height: var(--leading-heading-sm);
  font-weight: 600;
  overflow-wrap: anywhere;
}

.description {
  max-inline-size: 65ch;
  color: var(--muted-foreground);
  overflow-wrap: anywhere;
}
.description > p {
  margin: 0;
}

.action {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-inline);
}

/* end: the action shares the row with the text while the text keeps 16rem,
   then drops under it, as Card Heading's actions do. Two classes to beat
   Card's flex-direction. The action stays at the top, by the title, when
   the description runs to several lines. */
.actionPanel.end {
  flex-flow: row wrap;
  align-items: flex-start;
  justify-content: space-between;
}
.end > .text {
  flex: 1 1 16rem;
}

/* The edge says "careful" before the button does, on every side and in
   every appearance, flat surface included. [class] lifts it over Card's
   two-class appearance rules, whichever stylesheet loads last. */
.actionPanel.danger[class] {
  border-color: var(--destructive);
}
